def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    emit(out, "Start from the input; find complete two-colour motifs as templates.")
    temps = []
    for o in objects(g, bg=bg, diagonal=True, multicolour=True):
        cols = set(int(g[y, x]) for y, x in o["cells"])
        if len(cols) < 2:
            continue
        y0, x0, y1, x1 = o["box"]
        cy, cx = (y0 + y1) // 2, (x0 + x1) // 2
        c = int(g[cy, cx])
        sur = [(y - cy, x - cx) for y, x in o["cells"] if (y, x) != (cy, cx)]
        s = int(g[sur[0][0] + cy, sur[0][1] + cx])
        temps.append((c, s, sur))
    singles = set()
    for o in objects(g, bg=bg, diagonal=True, multicolour=True):
        if o["size"] == 1:
            singles.add(o["cells"][0])
    for c, s, sur in temps:
        # centre-only fragments: draw the surround
        for (y, x) in sorted(singles):
            if int(g[y, x]) == c:
                for dy, dx in sur:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W:
                        out[yy, xx] = s
                emit(out, f"Lone centre {c} at ({y},{x}): draw the {s} surround of its template.")
        # surround-only fragments: fill the centre
        for y in range(H):
            for x in range(W):
                if g[y, x] != bg:
                    continue
                ok = True
                for dy, dx in sur:
                    yy, xx = y + dy, x + dx
                    if not (0 <= yy < H and 0 <= xx < W) or g[yy, xx] != s:
                        ok = False
                        break
                if ok:
                    out[y, x] = c
                    emit(out, f"Surround of {s} without centre at ({y},{x}): fill centre with {c}.")
    emit(out, "All partial motifs completed.")
    return out
